Item.method_code:
function processPasswordChange(val) {
	if (document.item && this.form.password.value !== '') {
		const oldVal = aras.getItemProperty(document.item, 'confirm_password');
		if (oldVal != val) {
			aras.setItemProperty(document.item, 'confirm_password', val);
		}
		const flagNm = 'isPwdChangedByOnChangeMethod_2778060B48214BCF95163B47603AC135';
		const f = window[flagNm];
		const invalidPwdMessage = isPwdValidMessage.call(this);
		if (invalidPwdMessage && !(f && !this.form.password.value)) {
			const params = {
				buttons: {
					btnYes: aras.getResource('', 'common.ok'),
					btnCancel: aras.getResource('', 'common.cancel')
				},
				defaultButton: 'btnCancel',
				aras: aras,
				message: aras.getResource('', 'imports_core.new_pwd_cannot_be_set', invalidPwdMessage),
				dialogWidth: 300,
				dialogHeight: 200,
				center: true,
				content: 'groupChgsDialog.html'
			};

			const win = aras.getMostTopWindowWithAras(window);
			return win.ArasModules.Dialog.show('iframe', params).promise.then(function(res) {
				if (res === 'btnYes') {
					setTimeout('var fld = document.getElementById("' + this.form.password.getAttribute('id') + '"); if (fld){fld.focus()}', 10);
				} else {
					aras.setItemProperty(document.item, 'confirm_password', 'invalid_confirm_pwd');
					window[flagNm] = true;
					setTimeout('var fld = document.getElementById("' + this.form.password.getAttribute('id') + '"); if (fld){fld.value="";}', 10);
				}
			});
		}
		if (f) {
			window[flagNm] = false;
		}
	}
}

const currentItem = document.item;
if (!ArasModules.item.isEditState(currentItem.getAttribute('type'), currentItem.id)) {
	return;
}

const { variables } = window.aras.getMainWindow().store.getState();
if (variables['fips_mode']) {
	return ArasModules.cryptohash.SHA256(this.form['confirm_password'].value).then(processPasswordChange.bind(this));
}

return processPasswordChange.call(this, aras.calcMD5(this.form['confirm_password'].value));

function isPwdValidMessage() {
	const methNm = 'User_pwd_checkPolicy';
	const methNd = aras.getItem('Method', 'name=\'' + methNm + '\'', '<name>' + methNm + '</name>', 0);
	if (!methNd) {
		return aras.getResource('', 'imports_core.no_method_with_specified_name', methNm);
	}
	const methCode = aras.getItemProperty(methNd, 'method_code');
	const FunctionHook = Function;
	const func = new FunctionHook('plainPwd', 'variablesXML', methCode);
	return func(this.form.password.value, undefined);
}
